def init_agent_0():
    return {'t':jnp.int32(0), 'recipe':jnp.int32(-1), 'items':jnp.zeros((6,11,6),jnp.int32), 'known':jnp.int32(-1), 'age':jnp.int32(100), 'dish':jnp.int32(0), 'partner_col':jnp.int32(-1), 'partner_kind':jnp.int32(-1), 'offer_age':jnp.int32(0), 'handoff':jnp.int32(0), 'last_action':jnp.int32(4), 'last_col':jnp.int32(5), 'last_face':jnp.int32(0), 'signal_age':jnp.int32(0), 'signal':jnp.int32(-1), 'signal_belief':jnp.zeros((88,),jnp.int32), 'trial_signal':jnp.int32(-1), 'trial_kind':jnp.int32(-1), 'pending':jnp.int32(0), 'last_kind':jnp.int32(1), 'idle':jnp.int32(0), 'busy':jnp.int32(0), 'prefetch':jnp.int32(0), 'server_evidence':jnp.int32(0)}


def init_agent_1():
    return init_agent_0()


def _decode(obs, reset, memory):
    memory=jax.tree.map(lambda fresh,old:jnp.where(reset,fresh,old),init_agent_0(),memory)
    loc=jnp.argmin(jnp.sum(jnp.abs(jnp.asarray(_PATCHES)-obs[None,:,:,22:32]),axis=(1,2,3)))
    r,c=jnp.asarray(_FLOOR)[loc]
    rr=r+jnp.arange(5)[:,None]-2
    cc=c+jnp.arange(5)[None,:]-2
    valid=(rr>=0)&(rr<6)&(cc>=0)&(cc<11)
    items=memory['items'].at[jnp.where(valid,rr,6),jnp.where(valid,cc,11)].set(obs[:,:,32:38],mode='drop')
    inv=obs[2,2,5:11]
    face=jnp.argmax(obs[2,2,1:5])
    partner=jnp.sum(obs[:,:,16:22],axis=(0,1))
    pot=jnp.sum(obs[:,:,32:38]*obs[:,:,24,None],axis=(0,1))
    timer=jnp.sum(obs[:,:,44])
    recipe_counts=jnp.sum(obs[:,:,40:44],axis=(0,1))
    recipe=jnp.where(jnp.sum(recipe_counts)>0,jnp.argmax(recipe_counts),memory['recipe'])
    mem={**memory,'t':memory['t']+1,'recipe':recipe.astype(jnp.int32),'items':items}
    return loc,r,c,face,inv,partner,pot,timer,recipe,mem


def _use(loc,face,target):
    return jnp.asarray(_ACTION)[loc,face,target].astype(jnp.int32)


def _choose(loc,face, mask):
    cost=jnp.where(mask.reshape(-1),jnp.asarray(_COST)[loc,face],10000)
    return jnp.argmin(cost), jnp.min(cost)<999


def _raw_source(loc,face,items,kind,prefer_counter=True):
    static=jnp.asarray(_STATIC)
    raw=(items[:,:,0]==0)&(items[:,:,1]==0)&(items[:,:,2+kind]>0)
    mask=(static[:,:,6+kind]>0)|((static[:,:,0]>0)&raw)
    cost=jnp.asarray(_COST)[loc,face]*4-raw.reshape(-1).astype(jnp.int32)*jnp.asarray(prefer_counter,jnp.int32)*5
    return jnp.argmin(jnp.where(mask.reshape(-1),cost,100000))


def _drop(loc,face,items):
    target,exists=_choose(loc,face,(jnp.asarray(_STATIC)[:,:,0]>0)&(jnp.sum(items,axis=-1)==0))
    return jnp.where(exists,_use(loc,face,target),4)


def agent_0_act(obs, reset, memory, rng):
    loc,r,c,face,inv,partner,pot,timer,recipe,mem=_decode(obs,reset,memory)
    total=jnp.sum(pot[2:])
    raw=(jnp.sum(inv[2:])>0)&(inv[1]==0)
    plate=(inv[0]>0)&(inv[1]==0)
    dish=inv[1]>0
    delivered=(mem['dish']>0)&(~dish)
    age=jnp.where(delivered,0,mem['age']+1)
    known=jnp.where(delivered,-1,mem['known'])
    partner_raw=(partner[1]==0)&(jnp.sum(partner[2:4])==1)
    partner_col=c+jnp.sum(obs[:,:,11]*jnp.arange(5)[None,:])-2
    partner_face=jnp.argmax(jnp.sum(obs[:,:,12:16],axis=(0,1)))
    partner_kind=jnp.argmax(partner[2:])
    arriving=((mem['partner_col']==4)&(partner_face==2))|((mem['partner_col']==6)&(partner_face==3))
    arriving=arriving&(mem['partner_kind']==partner_kind)
    central=(partner_col==5)&((partner_face==0)|arriving)
    incoming=((partner_col<5)&(partner_face==2))|((partner_col>5)&(partner_face==3))
    previous_confirm=(mem['partner_col']>=3)&(mem['partner_col']<=7)&(mem['partner_kind']==partner_kind)
    offer_age=jnp.where(partner_raw&(partner_col==mem['partner_col'])&(partner_kind==mem['partner_kind']),mem['offer_age']+1,0)
    persistent=(offer_age>=4)&(age>=4)
    fresh_selection=(mem['partner_kind']<0)&(partner_col==mem['partner_col'])&(partner_col>=3)&(partner_col<=7)
    intent=central|(incoming&previous_confirm)|persistent|fresh_selection
    known=jnp.where(partner_raw&intent&(age>=2),partner_kind,known)
    # Optional fallback for partners who stand still to communicate. It is
    # subordinate to actual ingredients and does not prescribe our lower role.
    visible=jnp.sum(obs[:,:,11])>0
    partner_empty=jnp.sum(partner)==0
    marker=(partner[5]==1)&(jnp.sum(partner)==1)
    cue_state=jnp.clip(partner_col,0,10)*8+partner_face*2+marker.astype(jnp.int32)
    signal=jnp.where(visible&(partner_empty|marker),cue_state,-1)
    signal_age=jnp.where((signal>=0)&(signal==mem['signal']),mem['signal_age']+1,0)
    actual_delivery=delivered&(mem['last_action']==5)&(mem['last_col']==5)&(mem['last_face']==0)
    pending=jnp.where(actual_delivery&(mem['trial_signal']>=0),1,mem['pending'])
    learn=(pending>0)&(age>=4)&(signal_age>=3)&(signal>=0)
    changed=signal!=mem['trial_signal']
    old_index=jnp.clip(mem['trial_signal'],0,87)
    new_index=jnp.clip(signal,0,87)
    old_score=mem['signal_belief'][old_index]
    old_update=jnp.where(changed,jnp.where(mem['trial_kind']==1,8,-8),old_score+jnp.where(mem['trial_kind']==1,-1,1))
    beliefs=mem['signal_belief'].at[old_index].set(jnp.where(learn,jnp.clip(old_update,-12,12),old_score))
    new_score=beliefs[new_index]
    beliefs=beliefs.at[new_index].set(jnp.where(learn&changed,jnp.where(mem['trial_kind']==1,-8,8),new_score))
    belief=beliefs[new_index]
    pending=jnp.where(learn,0,pending)
    moved=visible&(partner_col!=mem['partner_col'])
    idle=jnp.where((total>0)|partner_raw|dish|moved,0,mem['idle']+1)
    cue_fallback=(known<0)&(total==0)&(signal>=0)&(signal_age>=jnp.where(jnp.abs(belief)>=4,3,6))&(age>=jnp.where(jnp.abs(belief)>=4,4,8))
    blind_fallback=(known<0)&(total==0)&(idle>=40)&(age>=20)
    hint=jnp.where(partner_col==5,partner_face==2,partner_col>5).astype(jnp.int32)
    guessed=jnp.where(belief==0,hint,(belief>0).astype(jnp.int32))
    last_kind=jnp.where(dish,jnp.argmax(inv[2:]),mem['last_kind'])
    known=jnp.where(cue_fallback,guessed,jnp.where(blind_fallback,1-last_kind,known))
    trial_signal=jnp.where(cue_fallback,signal,jnp.where(blind_fallback,-1,mem['trial_signal']))
    trial_kind=jnp.where(dish,jnp.argmax(inv[2:]),jnp.where(cue_fallback|blind_fallback,known,mem['trial_kind']))
    known=jnp.where(total>0,jnp.minimum(jnp.argmax(pot[2:]),1),known)
    kind=jnp.maximum(known,0)
    pot_action=_use(loc,face,jnp.int32(27))
    plate_target,_=_choose(loc,face,jnp.asarray(_STATIC)[:,:,5]>0)
    old_items=jnp.where(reset,jnp.zeros_like(memory['items']),memory['items'])
    shared_cols=jnp.asarray([4,6])
    old_shared=old_items[2,shared_cols]
    new_shared=mem['items'][2,shared_cols]
    own_drop=(mem['last_action']==5)&(mem['last_face']==1)&(mem['last_col']==shared_cols)
    matching_new=(jnp.sum(old_shared,axis=-1)==0)&(new_shared[:,2+kind]>0)&(new_shared[:,1]==0)&(~own_drop)
    handoff=(mem['handoff']>0)|(jnp.any(matching_new)&(known>=0)&(total<3))
    source=_raw_source(loc,face,mem['items'],kind,handoff)
    wait=jnp.where(c<5,0,jnp.where(c>5,2,4))
    ready_wait=jnp.where((c!=5)|(face!=1),pot_action,4)
    left_empty=jnp.sum(mem['items'][2,4])==0
    right_empty=jnp.sum(mem['items'][2,6])==0
    stock_kind=jnp.where(left_empty&right_empty,jnp.where(c<=5,0,1),jnp.where(left_empty,0,1))
    stock_source=_choose(loc,face,jnp.asarray(_STATIC)[:,:,6+stock_kind]>0)[0]
    stock=(timer>=11)&(left_empty|right_empty)
    cooking_action=jnp.where(stock,_use(loc,face,stock_source),_use(loc,face,plate_target))
    empty_action=jnp.where((total==0)&(known<0),wait,jnp.where(total<3,_use(loc,face,source),cooking_action))
    raw_action=jnp.where((known>=0)&(total<3)&(inv[2+kind]>0),pot_action,_drop(loc,face,mem['items']))
    valid_dish=(inv[2]==3)|(inv[3]==3)
    drop_target,can_drop=_choose(loc,face,(jnp.asarray(_STATIC)[:,:,0]>0)&(jnp.sum(mem['items'],axis=-1)==0))
    dish_action=jnp.where(valid_dish|(~can_drop),_use(loc,face,jnp.int32(5)),_use(loc,face,drop_target))
    action=jnp.where(dish,dish_action,jnp.where(plate,jnp.where(pot[1]>0,pot_action,jnp.where(total==3,ready_wait,_drop(loc,face,mem['items']))),jnp.where(raw,raw_action,empty_action)))
    mem={**mem,'signal_age':signal_age.astype(jnp.int32),'signal':signal.astype(jnp.int32),'signal_belief':beliefs.astype(jnp.int32),'trial_signal':trial_signal.astype(jnp.int32),'trial_kind':trial_kind.astype(jnp.int32),'pending':pending.astype(jnp.int32),'last_kind':last_kind.astype(jnp.int32),'idle':idle.astype(jnp.int32),'known':known.astype(jnp.int32),'age':age.astype(jnp.int32),'dish':inv[1],'handoff':handoff.astype(jnp.int32),'last_action':action.astype(jnp.int32),'last_col':c.astype(jnp.int32),'last_face':face.astype(jnp.int32),'offer_age':offer_age.astype(jnp.int32),'partner_col':jnp.where(jnp.sum(obs[:,:,11])>0,partner_col,-1).astype(jnp.int32),'partner_kind':jnp.where(partner_raw,partner_kind,-1).astype(jnp.int32)}
    return action.astype(jnp.int32),mem,{'position':jnp.stack([r,c]),'pot':pot,'target':known,'timer':timer,'inv':inv,'partner':partner,'age':age,'handoff':handoff,'signal':signal,'belief':belief,'cue':cue_fallback,'blind':blind_fallback}


def agent_1_act(obs, reset, memory, rng):
    loc,r,c,face,inv,partner,pot,timer,recipe,mem=_decode(obs,reset,memory)
    total=jnp.sum(pot[2:])
    held=jnp.sum(inv)>0
    raw=(jnp.sum(inv[2:])>0)&(inv[1]==0)
    center=jnp.where(r>3,3,jnp.where(c<5,0,jnp.where(c>5,2,4)))
    kind=jnp.maximum(recipe,0)
    source=_raw_source(loc,face,mem['items'],kind)
    correct=inv[2+kind]>0
    transit=partner[1]>0
    pot_visible=jnp.sum(obs[:,:,24])>0
    partner_visible=jnp.sum(obs[:,:,11])>0
    busy=jnp.where(pot_visible&((total>=3)|transit),True,jnp.where(pot_visible&((total>0)|partner_visible)&(~transit),False,mem['busy']>0))
    can_add=(total<3)&(timer==0)&(pot[1]==0)&(~busy)
    upper_raw=(jnp.sum(partner[2:])>0)&(partner[1]==0)
    plate_wait=(partner[0]>0)&(partner[1]==0)&pot_visible&(total<3)
    server_evidence=jnp.where(upper_raw,0,jnp.minimum(32,mem['server_evidence']+plate_wait.astype(jnp.int32)))
    server=server_evidence>=8
    # Parking keeps carried ingredients semantically current across a recipe reset.
    walls=jnp.asarray(_STATIC)[:,:,0]>0
    vacant=jnp.sum(mem['items'],axis=-1)==0
    near=jnp.zeros((6,11),jnp.bool_).at[2,3].set(True).at[2,7].set(True).at[4,3].set(True).at[4,7].set(True)
    park_target,park_available=_choose(loc,face,near&vacant)
    exclusive=walls.at[2,4].set(False).at[2,6].set(False)
    any_target,any_available=_choose(loc,face,exclusive&vacant)
    park_target=jnp.where(park_available,park_target,any_target)
    park_action=jnp.where(park_available|any_available,_use(loc,face,park_target),center)
    cached=walls&(mem['items'][:,:,2+kind]>0)&(mem['items'][:,:,0]==0)&(mem['items'][:,:,1]==0)
    _,have_cache=_choose(loc,face,cached)
    prefetch=jnp.where((~busy)|held,False,jnp.where((timer>=18)&(~have_cache),True,mem['prefetch']>0))
    raw_action=jnp.where(busy,park_action,jnp.where(~correct,_drop(loc,face,mem['items']),jnp.where(can_add,_use(loc,face,jnp.int32(27)),center)))
    fetch=_use(loc,face,source)
    empty_action=jnp.where(recipe<0,center,jnp.where(busy,jnp.where(prefetch,fetch,center),fetch))
    direct_raw=jnp.where(~correct,_drop(loc,face,mem['items']),jnp.where(can_add,_use(loc,face,jnp.int32(27)),center))
    raw_action=jnp.where(server,direct_raw,raw_action)
    empty_action=jnp.where(server& (recipe>=0),fetch,empty_action)
    action=jnp.where(held,jnp.where(raw,raw_action,_drop(loc,face,mem['items'])),empty_action)
    mem={**mem,'busy':busy.astype(jnp.int32),'prefetch':prefetch.astype(jnp.int32),'server_evidence':server_evidence.astype(jnp.int32)}
    return action.astype(jnp.int32),mem,{'position':jnp.stack([r,c]),'pot':pot,'target':recipe,'timer':timer,'transit':transit,'inv':inv,'partner':partner,'busy':busy,'prefetch':prefetch,'server_evidence':server_evidence}
